class Dog {
  constructor(name) {
    this.name = name;
  }
  bark() {
    return this.name + " says woof";
  }
}

console.log(new Dog("Rex").bark());

class Animal {
  speak() {
    return "...";
  }
}

class Cat extends Animal {
  speak() {
    return "meow and " + super.speak();
  }
}

const c = new Cat();
console.log(c.speak(), c instanceof Animal);

